-- TerrainData.lua  (GENERADO por tools/fetch_satellite.py, no editar a mano)
-- Imagen satelital real de la Tierra: NASA GIBS BlueMarble_ShadedRelief_Bathymetry + ASTER_GDEM_Greyscale_Shaded_Relief (estilo relieve)
-- Fecha: estatica (sin nubes) | Cuadricula 960x400 | Latitudes 84N a 60S | Paleta de 256 colores.
local TerrainData = {}

TerrainData.W = 960
TerrainData.H = 400
TerrainData.SOURCE = "NASA GIBS BlueMarble_ShadedRelief_Bathymetry + ASTER_GDEM_Greyscale_Shaded_Relief (estilo relieve)"
TerrainData.DATE = "estatica (sin nubes)"

local PALETTE = ""

local INDICES = {
	"",
	"",
	"",
	"",
	"",
	"",
	"",
	"",
	"",
	"",
	"",
	"",
	"",
